(()=>{'use strict';const reduced=matchMedia('(prefers-reduced-motion: reduce)');document.querySelectorAll('.route-comparison').forEach(card=>{const play=()=>{if(reduced.matches)return;card.classList.remove('is-playing');requestAnimationFrame(()=>requestAnimationFrame(()=>card.classList.add('is-playing')))};card.querySelector('.route-replay')?.addEventListener('click',play);if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){play();observer.disconnect()}},{threshold:.25});observer.observe(card)}else play()})})();
